280: 	if err != nil {
281: 		return nil, err
282: 	}
283: 	plan := &plannedAutomation{
284: 		record:   record,
285: 		matched:  matched,
286: 		decision: decision,
287: 	}
288: 	if reason == "" {
289: 		plan.kind = plannedOutcomeRun
290: 	} else {
291: 		plan.kind = plannedOutcomeSkip
292: 		plan.reason = reason
293: 	}
294: 	return plan, nil
