297: // commitDeviceFact writes every planned outcome in Automation ID order inside the caller's transaction.
298: func (repo *AutomationRepository) commitDeviceFact(
299: 	ctx context.Context,
300: 	queries *dbsqlc.Queries,
301: 	plans []plannedAutomation,
302: 	summary automations.DeviceFactSummary,
303: 	admittedAt time.Time,
304: 	result *automations.AdmissionResult,
305: ) error {
306: 	for _, plan := range plans {
307: 		result.Outcome.MatchedAutomations++
308: 		switch plan.kind {
309: 		case plannedOutcomeDuplicate:
310: 			result.Outcome.DuplicateOutcomes++
311: 		case plannedOutcomeRun:
312: 			runID, err := repo.newRunID()
313: 			if err != nil {
314: 				return fmt.Errorf("allocate automation run ID: %w", err)
315: 			}
316: 			run := automations.NewRunSnapshot(
317: 				plan.record,
318: 				runID,
319: 				automations.RunSourceDeviceFact,
320: 				&summary,
321: 				plan.matched,
322: 				plan.decision,
323: 				admittedAt,
324: 			)
325: 			if err = repo.persistRun(ctx, queries, run); err != nil {
326: 				return err
327: 			}
328: 			if err = repo.writeReceipt(
329: 				ctx, queries, summary.FactID, plan.record.ID,
330: 				automations.HistoryRun, string(run.ID),
331: 			); err != nil {
332: 				return err
333: 			}
334: 			result.Outcome.StartedRuns++
335: 			result.StartedRuns = append(result.StartedRuns, run)
336: 		case plannedOutcomeSkip:
337: 			skip, err := repo.recordSkip(ctx, queries, plan, summary, admittedAt)
338: 			if err != nil {
339: 				return err
340: 			}
341: 			result.Outcome.RecordedSkips++
342: 			result.Skips = append(result.Skips, skip)
343: 		}
344: 	}
345: 	return nil
346: }
